import json
def mc(q, ok, w1, w2, why): return {"t":"mc","q":q,"o":[ok,w1,w2],"a":0,"why":why}
def fill(q, ans, why): return {"t":"fill","q":q,"a":ans if isinstance(ans,list) else [ans],"why":why}
def M(kind,title,source,url,minutes,focus): return {"kind":kind,"title":title,"source":source,"url":url,"minutes":minutes,"focus":focus}
def yt(vid,title,src,mins,focus): return M("video",title,"YouTube · "+src,"https://www.youtube.com/watch?v="+vid,mins,focus)
def N(h,t): return {"heading":h,"text":t}

MOD="https://www.goethe.de/pro/relaunch/prf/materialien/B1/b1_modellsatz_erwachsene.pdf"
UEB="https://www.goethe.de/pro/relaunch/prf/materialien/B1/B1_Uebungssatz_Erwachsene.pdf"
ONL="https://www.goethe.de/ins/de/de/spr/prf/gzb1/ueb.html"
def modell(mins,focus): return M("pdf","Goethe-Zertifikat B1 – Modellsatz (adults)","Goethe-Institut",MOD,mins,focus)
def uebung(mins,focus): return M("pdf","Goethe-Zertifikat B1 – Übungssatz (adults)","Goethe-Institut",UEB,mins,focus)
def online(mins,focus): return M("exercise","Goethe-Zertifikat B1 – practice tests with audio","Goethe-Institut",ONL,mins,focus)

